function comparePreview(entries, count) {
  const preview = peekLine(entries, count);
  return { preview, entries };
}

function peekLine(entries, count) { return entries.splice(0, count); }

function compareOrder(readings) {
  const sorted = sortReadings(readings);
  return [sorted, readings];
}

function sortReadings(readings) { return readings.toSorted(); }

function checkSettings(defaults, overrides) {
  const merged = mergeSettings(defaults, overrides);
  return { defaults, merged };
}

function mergeSettings(defaults, overrides) { return Object.assign(defaults, overrides); }

function rackLabel(prefix, number) {
  const record = { prefix, number, label: () => this.prefix + '-' + this.number };
  return record.label();
}

function countMaterials(names) {
  const counts = {};
  for (const name of names) counts[name] = (counts[name] ?? 0) + 1;
  return Object.entries(counts);
}

class SupplyBox {
  constructor(initial) { this.quantity = initial; }
  receive(count) { this.quantity = count; }
  total() { return this.quantity; }
}
function runBoxes(left, right, leftAdd, rightAdd) {
  const first = new SupplyBox(left);
  const second = new SupplyBox(right);
  first.receive(leftAdd);
  second.receive(rightAdd);
  first.receive(2);
  return [first.total(), second.total()];
}

function labelRange(first, last) {
  const labels = [];
  for (let number = first; number <= last + 1; number++) labels.push(number);
  return labels;
}
